import { defineCollection, reference } from "astro:content"
import { z } from "astro/zod"

import { pageLoader } from "@/lib/page-loader"

const common = z.object({
  title: z.string().trim().min(1),
  description: z.string().trim().min(1),
  translationKey: z.string().trim().min(1).optional(),
  updatedAt: z.coerce.date().optional(),
  seo: z
    .object({
      title: z.string().trim().min(1).optional(),
      description: z.string().trim().min(1).optional(),
      canonical: z.url().optional(),
      noindex: z.boolean().optional(),
      nofollow: z.boolean().optional(),
    })
    .strict()
    .optional(),
})

export const collections = {
  pages: defineCollection({
    loader: pageLoader(),
    schema: z.discriminatedUnion("type", [
      common.extend({ type: z.literal("page") }).strict(),
      common
        .extend({
          type: z.literal("overview"),
          entries: z.array(reference("pages")).optional(),
        })
        .strict(),
    ]),
  }),
}

---
import { siteConfig } from "@/site.config"

import {
  getPageAlternates,
  getPageBreadcrumbs,
  getPageLocale,
} from "@/lib/page-paths"
import type { Page } from "@/lib/pages"
import { getStructuredData } from "@/lib/seo"
import {
  Layout,
  LayoutBody,
  LayoutHead,
  LayoutMain,
} from "@/components/ui/layout"

type Props = { page: Page; pages: Page[] }
const { page, pages } = Astro.props
const context = {
  locale: getPageLocale(page, siteConfig.i18n),
  breadcrumbs: getPageBreadcrumbs(pages, page, siteConfig.i18n),
}
const alternates = getPageAlternates(pages, page, siteConfig.i18n)
---

<Layout lang={context.locale}>
  <LayoutHead
    name={siteConfig.name}
    title={page.data.title}
    description={page.data.description}
    {...page.data.seo}
    canonical={page.data.seo?.canonical ??
      new URL(Astro.url.pathname, siteConfig.site).href}
    alternates={alternates.map((item) => ({
      ...item,
      href: new URL(item.href, siteConfig.site).href,
    }))}
    structuredData={getStructuredData(page, context, siteConfig)}
  />
  <LayoutBody
    ><LayoutMain class="mx-auto w-full max-w-5xl gap-8 px-6 py-12"
      ><slot /></LayoutMain
    ></LayoutBody
  >
</Layout>

import { existsSync } from "node:fs"
import { glob } from "astro/loaders"
import type { Loader } from "astro/loaders"

export function pageLoader(base = "src/content/pages"): Loader {
  const paths = new Map<string, string>()
  const loader = glob({
    base,
    pattern: "**/[^_]*.{md,mdx}",
    generateId: ({ entry, data, base }) => {
      if ("slug" in data)
        throw new Error(
          `Remove the slug override in "${entry}". Page URLs are determined by file paths.`
        )
      const id = entry.replace(/\.(md|mdx)$/, "").replace(/\/index$/, "")
      if (/[?#%\\\s]/.test(id))
        throw new Error(
          `Invalid page path "${entry}". Use URL-safe file names.`
        )
      const previous = paths.get(id)
      if (
        previous &&
        previous !== entry &&
        existsSync(new URL(encodeURI(previous), base))
      )
        throw new Error(
          `Page route collision: "${previous}" and "${entry}" both map to "${id}".`
        )
      paths.set(id, entry)
      return id
    },
  })
  return {
    ...loader,
    name: "pages",
    async load(context) {
      paths.clear()
      await loader.load(context)
    },
  }
}

export interface LocaleConfig {
  defaultLocale: string
  locales: readonly string[]
  prefixDefaultLocale: boolean
}

export interface RoutablePage {
  id: string
  data: {
    type: string
    title: string
    description: string
    translationKey?: string
    updatedAt?: Date
    seo?: { canonical?: string; noindex?: boolean }
  }
}

export const normalizePath = (path: string) =>
  path === "/" ? path : path.replace(/\/+$/, "")

export const getPageHref = (page: Pick<RoutablePage, "id">) =>
  page.id === "index" ? "/" : `/${page.id}/`

export const getPageLocale = (
  page: Pick<RoutablePage, "id">,
  config: LocaleConfig
) => {
  const first = page.id.split("/")[0]
  return config.locales.includes(first) ? first : config.defaultLocale
}

export const getLocaleHome = (locale: string, config: LocaleConfig) =>
  locale === config.defaultLocale && !config.prefixDefaultLocale
    ? "/"
    : `/${locale}/`

export const getPageChildren = <T extends RoutablePage>(
  pages: T[],
  parent: Pick<RoutablePage, "id">,
  type?: T["data"]["type"]
) => {
  const prefix = parent.id === "index" ? "" : `${parent.id}/`
  return pages.filter((page) => {
    if (page.id === parent.id || !page.id.startsWith(prefix)) return false
    return (
      !page.id.slice(prefix.length).includes("/") &&
      (!type || page.data.type === type)
    )
  })
}

export const resolvePageReference = <T extends RoutablePage>(
  pages: T[],
  id: string,
  expectedType?: T["data"]["type"]
) => {
  const page = pages.find((entry) => entry.id === id)
  if (!page) throw new Error(`Unknown page reference "${id}".`)
  if (expectedType && page.data.type !== expectedType) {
    throw new Error(
      `Page "${id}" must have type "${expectedType}", received "${page.data.type}".`
    )
  }
  return page
}

export const getPageAlternates = <T extends RoutablePage>(
  pages: T[],
  page: T,
  config: LocaleConfig
) => {
  if (!page.data.translationKey) return []
  return pages
    .filter((entry) => entry.data.translationKey === page.data.translationKey)
    .map((entry) => ({
      locale: getPageLocale(entry, config),
      href: getPageHref(entry),
    }))
}

export const validatePageTree = <T extends RoutablePage>(
  pages: T[],
  config: LocaleConfig
) => {
  const urls = new Set<string>()
  const translations = new Map<string, string>()
  for (const page of pages) {
    const href = getPageHref(page)
    if (urls.has(href)) throw new Error(`Duplicate page URL "${href}".`)
    urls.add(href)
    const first = page.id.split("/")[0]
    const locale = getPageLocale(page, config)
    if (config.prefixDefaultLocale && !config.locales.includes(first)) {
      throw new Error(
        `Page "${page.id}" must live in a configured locale folder.`
      )
    }
    if (!config.prefixDefaultLocale && first === config.defaultLocale) {
      throw new Error(
        `Default-locale page "${page.id}" must live outside the locale folder.`
      )
    }
    if (page.data.translationKey) {
      const key = `${locale}:${page.data.translationKey}`
      if (translations.has(key))
        throw new Error(
          `Duplicate translation "${key}" on "${page.id}" and "${translations.get(key)}".`
        )
      translations.set(key, page.id)
      const counterpart = pages.find(
        (entry) =>
          entry.data.translationKey === page.data.translationKey &&
          entry.data.type !== page.data.type
      )
      if (counterpart)
        throw new Error(
          `Translations "${page.id}" and "${counterpart.id}" must use the same page type.`
        )
    }
  }
}

export const validatePageLinks = (
  value: unknown,
  pages: RoutablePage[],
  owner: string
): void => {
  if (!value || typeof value !== "object") return
  if (Array.isArray(value)) {
    value.forEach((entry) => validatePageLinks(entry, pages, owner))
    return
  }
  const record = value as Record<string, unknown>
  if (record.collection === "pages" && typeof record.id === "string") {
    resolvePageReference(
      pages,
      record.id,
      typeof record.expectedType === "string" ? record.expectedType : undefined
    )
  }
  if (
    typeof record.href === "string" &&
    record.href.startsWith("/") &&
    !record.href.startsWith("//")
  ) {
    const path = record.href.split(/[?#]/)[0]
    if (
      !pages.some(
        (page) => normalizePath(getPageHref(page)) === normalizePath(path)
      )
    ) {
      throw new Error(
        `Unknown internal page link "${record.href}" in ${owner}. Use a page URL or an explicit external URL.`
      )
    }
  }
  Object.values(record).forEach((entry) =>
    validatePageLinks(entry, pages, owner)
  )
}

export const getPageBreadcrumbs = <T extends RoutablePage>(
  pages: T[],
  page: T,
  config: LocaleConfig
) => {
  const locale = getPageLocale(page, config)
  const home = getLocaleHome(locale, config)
  const href = getPageHref(page)
  return pages
    .filter((entry) => {
      const candidate = getPageHref(entry)
      return (
        getPageLocale(entry, config) === locale &&
        (candidate === home ||
          candidate === href ||
          (candidate !== "/" && href.startsWith(candidate)))
      )
    })
    .sort((a, b) => getPageHref(a).length - getPageHref(b).length)
    .map((entry) => ({ label: entry.data.title, href: getPageHref(entry) }))
}

export const getMarkdownHref = (href: string) =>
  href === "/" ? "/index.md" : `${href.replace(/\/$/, "")}.md`

import { getCollection, type CollectionEntry } from "astro:content"
import { siteConfig } from "@/site.config"

import {
  getPageChildren,
  getPageLocale,
  resolvePageReference,
  validatePageLinks,
  validatePageTree,
} from "@/lib/page-paths"

export type Page = CollectionEntry<"pages">
export const getPages = async () => {
  const pages = await getCollection("pages")
  validatePageTree(pages, siteConfig.i18n)
  pages.forEach((page) => validatePageLinks(page.data, pages, page.id))
  return pages
}
export const getOverviewEntries = (pages: Page[], page: Page) => {
  const locale = getPageLocale(page, siteConfig.i18n)
  const entries =
    page.data.type === "overview" && page.data.entries
      ? page.data.entries.map((reference) =>
          resolvePageReference(pages, reference.id)
        )
      : getPageChildren(pages, page)
          .filter((entry) => getPageLocale(entry, siteConfig.i18n) === locale)
          .sort((a, b) => a.data.title.localeCompare(b.data.title, locale))
  if (entries.some((entry) => getPageLocale(entry, siteConfig.i18n) !== locale))
    throw new Error(`Overview "${page.id}" references another locale.`)
  return entries
}
export async function getPagesByType<T extends Page["data"]["type"]>(type: T) {
  return (await getPages()).filter(
    (page): page is Page & { data: Extract<Page["data"], { type: T }> } =>
      page.data.type === type
  )
}

import { getPageHref, type RoutablePage } from "./page-paths"

type Context = {
  locale: string
  breadcrumbs: { href: string; label: string }[]
}

export function getStructuredData(
  page: RoutablePage,
  context: Context,
  site: { site: string; name: string },
  organization?: { name: string; url: string }
) {
  const url = new URL(page.data.seo?.canonical ?? getPageHref(page), site.site)
    .href
  const websiteId = new URL("/#website", site.site).href
  const organizationId = new URL("/#organization", site.site).href
  const webpageId = `${url}#webpage`
  const graph: Record<string, unknown>[] = [
    {
      "@type": "WebSite",
      "@id": websiteId,
      url: new URL("/", site.site).href,
      name: site.name,
      ...(organization && { publisher: { "@id": organizationId } }),
    },
    {
      "@type": page.data.type === "overview" ? "CollectionPage" : "WebPage",
      "@id": webpageId,
      url,
      name: page.data.title,
      description: page.data.description,
      inLanguage: context.locale,
      isPartOf: { "@id": websiteId },
      ...(page.data.updatedAt && {
        dateModified: page.data.updatedAt.toISOString(),
      }),
      ...(context.breadcrumbs.length > 1 && {
        breadcrumb: { "@id": `${url}#breadcrumb` },
      }),
    },
  ]
  if (organization)
    graph.push({
      "@type": "Organization",
      "@id": organizationId,
      ...organization,
    })
  if (page.data.type === "doc")
    graph.push({
      "@type": "TechArticle",
      "@id": `${url}#article`,
      headline: page.data.title,
      description: page.data.description,
      inLanguage: context.locale,
      mainEntityOfPage: { "@id": webpageId },
      ...(page.data.updatedAt && {
        dateModified: page.data.updatedAt.toISOString(),
      }),
    })
  if (context.breadcrumbs.length > 1)
    graph.push({
      "@type": "BreadcrumbList",
      "@id": `${url}#breadcrumb`,
      itemListElement: context.breadcrumbs.map((item, index) => ({
        "@type": "ListItem",
        position: index + 1,
        name: item.label,
        item: new URL(item.href, site.site).href,
      })),
    })
  return { "@context": "https://schema.org", "@graph": graph }
}

import {
  getPageAlternates,
  getPageHref,
  type LocaleConfig,
  type RoutablePage,
} from "./page-paths"

export const escapeXml = (value: string) =>
  value.replace(
    /[<>&"']/g,
    (char) =>
      ({
        "<": "&lt;",
        ">": "&gt;",
        "&": "&amp;",
        '"': "&quot;",
        "'": "&apos;",
      })[char]!
  )

export function renderSitemap(
  pages: RoutablePage[],
  site: string,
  locales: LocaleConfig
) {
  const indexable = pages.filter(
    (page) =>
      !page.data.seo?.noindex &&
      (!page.data.seo?.canonical ||
        page.data.seo.canonical === new URL(getPageHref(page), site).href)
  )
  const entries = indexable
    .map((page) => {
      const url = escapeXml(new URL(getPageHref(page), site).href)
      const alternates = getPageAlternates(indexable, page, locales)
        .map(
          (alternate) =>
            `<xhtml:link rel="alternate" hreflang="${escapeXml(alternate.locale)}" href="${escapeXml(new URL(alternate.href, site).href)}"/>`
        )
        .join("")
      return `<url><loc>${url}</loc>${page.data.updatedAt ? `<lastmod>${page.data.updatedAt.toISOString()}</lastmod>` : ""}${alternates}</url>`
    })
    .join("")
  return `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">${entries}</urlset>`
}

---
import { getPageHref } from "@/lib/page-paths"
import { getPages } from "@/lib/pages"
import LayoutRenderer from "@/components/layout-renderer.astro"

export async function getStaticPaths() {
  const pages = await getPages()
  return pages.map((page) => {
    return {
      params: {
        page: getPageHref(page).slice(1, -1) || undefined,
      },
      props: page,
    }
  })
}
---

<LayoutRenderer {...Astro.props} />

import { siteConfig } from "@/site.config"

import { getPages } from "@/lib/pages"
import { renderSitemap } from "@/lib/sitemap"

export async function GET() {
  return new Response(
    renderSitemap(await getPages(), siteConfig.site, siteConfig.i18n),
    { headers: { "Content-Type": "application/xml; charset=utf-8" } }
  )
}

import { siteConfig } from "@/site.config"

import { escapeXml } from "@/lib/sitemap"

export function GET() {
  return new Response(
    `<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>${escapeXml(new URL("/sitemap-0.xml", siteConfig.site).href)}</loc></sitemap></sitemapindex>`,
    { headers: { "Content-Type": "application/xml; charset=utf-8" } }
  )
}

export const siteConfig = {
  site: "https://example.com",
  name: "My website",
  i18n: { defaultLocale: "en", locales: ["en"], prefixDefaultLocale: false },
}
